def roman_to_int(s):
    pairs = {"IV": 4, "IX": 9, "XL": 40, "XC": 90, "CD": 400, "CM": 900}
    singles = {"I": 1, "V": 5, "X": 10, "L": 50, "C": 100, "D": 500, "M": 1000}
    total = 0
    i = 0
    while i < len(s):
        if s[i:i + 2] in pairs:                                  # check against the fixed list of 6 special pairs
            total += pairs[s[i:i + 2]]
            i += 2
        else:
            total += singles[s[i]]
            i += 1
    return total


if __name__ == "__main__":
    s = "MCMXCIV"
    print(roman_to_int(s))

