import java.util.*;

public class Main {
    int romanToInt(String s) {
        Map<String, Integer> pairs = new HashMap<>();
        pairs.put("IV", 4); pairs.put("IX", 9); pairs.put("XL", 40);
        pairs.put("XC", 90); pairs.put("CD", 400); pairs.put("CM", 900);
        Map<Character, Integer> singles = new HashMap<>();
        singles.put('I', 1); singles.put('V', 5); singles.put('X', 10);
        singles.put('L', 50); singles.put('C', 100); singles.put('D', 500); singles.put('M', 1000);
        int total = 0;
        int i = 0;
        while (i < s.length()) {
            if (i + 1 < s.length() && pairs.containsKey(s.substring(i, i + 2))) { // check against the 6 special pairs
                total += pairs.get(s.substring(i, i + 2));
                i += 2;
            } else {
                total += singles.get(s.charAt(i));
                i++;
            }
        }
        return total;
    }

    public static void main(String[] args) {
        String s = "MCMXCIV";
        Main solution = new Main();
        System.out.println(solution.romanToInt(s));
    }
}

