def roman_to_int(s):
    values = {"I": 1, "V": 5, "X": 10, "L": 50, "C": 100, "D": 500, "M": 1000}
    total = 0
    largest_so_far = 0
    for ch in reversed(s):
        value = values[ch]
        if value < largest_so_far:
            total -= value                                       # this symbol comes before something larger
        else:
            total += value
            largest_so_far = value
    return total


if __name__ == "__main__":
    s = "MCMXCIV"
    print(roman_to_int(s))

